#!/usr/bin/env node
/**
 * Evidence publication.
 *
 * Copies from `e2e/.artifacts/evidence/` (gitignored, regenerated by every
 * Playwright run) into `docs/platform/evidence/product/` (committed):
 *
 * - every `*.json` manifest, so a reviewer can audit provenance for every
 *   frame a run captured, not only the ones that got committed as images
 * - only the PNGs whose slug matches the allowlist below — the rubric-named
 *   states a reviewer is expected to find, not whatever a run happened to
 *   produce
 *
 * Publication is a separate, explicit command rather than a CI side effect:
 * committed frames change only when someone runs this and reviews the diff.
 * It never deletes a sibling file it did not write, so hand-authored content
 * in the same directory (the README, the design references) is untouched.
 *
 * Prereqs: run the Playwright suites first so `.artifacts/evidence/` is
 * fresh — `pnpm e2e`, `pnpm e2e:roles`, `pnpm e2e:a11y-roles` (the a11y
 * project itself captures no screenshots; the evidence PNGs come from the
 * evidence-run suites).
 */
import { readdir, mkdir, copyFile, readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const WEB_ROOT = path.resolve(fileURLToPath(import.meta.url), "../../..");
const REPO_ROOT = path.resolve(WEB_ROOT, "../..");
const SOURCE_DIR = path.join(WEB_ROOT, "e2e", ".artifacts", "evidence");
const TARGET_DIR = path.join(REPO_ROOT, "docs", "phase2", "evidence", "product");

/**
 * Rubric-named states worth a committed PNG: the three approved routes at
 * every viewport, plus the degraded/denial/policy states a reviewer needs to
 * see to believe the product is honest about them. A slug matches when it
 * *contains* one of these — `evidence-manifest.ts` builds slugs as
 * `route--state--role--project`, so this list only needs to name the state.
 */
const STATE_ALLOWLIST = [
  "success",
  "degraded",
  "forbidden",
  "cost-cap-denied",
  "stale-fencing",
  "quota-exhausted",
  "streaming",
];

async function main() {
  let entries;
  try {
    entries = await readdir(SOURCE_DIR, { withFileTypes: true });
  } catch (error) {
    if (error.code === "ENOENT") {
      console.error(
        `no evidence found at ${SOURCE_DIR} — run the Playwright suites first (pnpm e2e && pnpm e2e:roles)`,
      );
      process.exit(1);
    }
    throw error;
  }

  await mkdir(TARGET_DIR, { recursive: true });

  let manifests = 0;
  let images = 0;
  let skipped = 0;

  for (const entry of entries) {
    if (!entry.isFile()) continue;

    if (entry.name.endsWith(".json")) {
      await copyFile(path.join(SOURCE_DIR, entry.name), path.join(TARGET_DIR, entry.name));
      manifests += 1;
      continue;
    }

    if (entry.name.endsWith(".png")) {
      const slug = entry.name.replace(/\.png$/, "");
      if (STATE_ALLOWLIST.some((state) => slug.includes(state))) {
        await copyFile(path.join(SOURCE_DIR, entry.name), path.join(TARGET_DIR, entry.name));
        images += 1;
      } else {
        skipped += 1;
      }
    }
  }

  console.log(
    `published ${manifests} manifest(s) and ${images} image(s) to ${path.relative(REPO_ROOT, TARGET_DIR)}; skipped ${skipped} non-allowlisted image(s)`,
  );

  if (manifests === 0) {
    console.error("no manifests found — did the Playwright suites actually run?");
    process.exit(1);
  }
}

// Sanity check the allowlist itself matches at least one manifest's `state`
// field on every run with fresh evidence, so a rename in evidence-manifest.ts
// fails loudly here instead of silently publishing zero images.
async function warnOnUnmatchedStates() {
  let files;
  try {
    files = (await readdir(SOURCE_DIR)).filter((name) => name.endsWith(".json"));
  } catch {
    return;
  }
  const seenStates = new Set();
  for (const file of files) {
    const manifest = JSON.parse(await readFile(path.join(SOURCE_DIR, file), "utf8"));
    seenStates.add(manifest.state);
  }
  const unmatched = [...seenStates].filter(
    (state) => !STATE_ALLOWLIST.some((allowed) => state.includes(allowed) || allowed.includes(state)),
  );
  if (unmatched.length > 0) {
    console.warn(
      `note: captured state(s) not in the allowlist and therefore never published as PNGs: ${unmatched.join(", ")}`,
    );
  }
}

await warnOnUnmatchedStates();
await main();
